#include "pattern_fixed_project.h"
#include "pattern_codec_source.h"
#include "pattern_storage_codec.h"
#include "pattern_flash_store.h"
#include <stdint.h>
#include <string.h>
int fm1_fixed_project_bridge_result(int rc){if(rc==FM1_FIXED_FULL)return PFS_FULL;if(rc==PS_OK)return PFS_OK;if(rc==PS_EMPTY)return PFS_EMPTY;if(rc==PS_IO)return PFS_IO;return PFS_INVALID;}
static uint32_t get32(const uint8_t *p){return (uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static void put32(uint8_t *p,uint32_t x){p[0]=(uint8_t)x;p[1]=(uint8_t)(x>>8);p[2]=(uint8_t)(x>>16);p[3]=(uint8_t)(x>>24);}
static int overlap(const void *a,size_t n,const void *b,size_t m){uintptr_t x=(uintptr_t)a,y=(uintptr_t)b;return n&&m&&(x<=y?y-x<n:x-y<m);}
int fm1_fixed_project_source_separate(const fm1_project_source *s,const void *p,size_t pn){const br_pattern_bank *b;const fm1_project_work *w;if(!s||!p||!s->session||!s->bank||!s->live||!s->work)return 0;b=s->bank;w=s->work;if((b->capacity&&!b->arena)||(w->arena_capacity&&!w->arena)||(w->compressed_capacity&&!w->compressed)||!w->pattern||!w->session)return 0;return !overlap(p,pn,s,sizeof *s)&&!overlap(p,pn,s->session,FM1_PROJECT_SESSION)&&!overlap(p,pn,b,sizeof *b)&&!overlap(p,pn,b->arena,b->capacity)&&!overlap(p,pn,s->live,sizeof *s->live)&&!overlap(p,pn,w,sizeof *w)&&!overlap(p,pn,w->pattern,sizeof *w->pattern)&&!overlap(p,pn,w->session,FM1_PROJECT_SESSION)&&!overlap(p,pn,w->arena,w->arena_capacity)&&!overlap(p,pn,w->compressed,w->compressed_capacity);}
static int configured(const ps_store *s){return s&&s->payload_size==FM1_FIXED_PAYLOAD&&s->valid==fm1_fixed_project_valid;}
int fm1_fixed_project_valid(const void *p,uint32_t n){const uint8_t *b=p;uint32_t len,decoded,i;if(!p||n!=FM1_FIXED_PAYLOAD)return 0;len=get32(b);if(len<12||len>FM1_FIXED_COMPRESSED_MAX||memcmp(b+4,"PSC\3",4))return 0;decoded=get32(b+8);if(decoded<FM1_PROJECT_HEADER_BYTES+FM1_PROJECT_SESSION||decoded>FM1_PROJECT_MAX)return 0;for(i=4+len;i<n;i++)if(b[i]!=0xffu)return 0;return fm1_pattern_codec_validate(b+4,len,decoded)==FM1_CODEC_OK;}
static int save(const ps_store *s,uint32_t slot,const char *name,fm1_project_source *source,uint8_t *payload,uint8_t *verify,fm1_fixed_preflight_fn preflight,void *prectx,pops_certify_fn cert,void *ctx,int initialize){size_t len;int rc;if(!configured(s)||!source||!payload||!verify||!preflight||!fm1_fixed_project_source_separate(source,payload,FM1_FIXED_PAYLOAD)||!fm1_fixed_project_source_separate(source,verify,FM1_FIXED_PAYLOAD)||overlap(payload,FM1_FIXED_PAYLOAD,verify,FM1_FIXED_PAYLOAD))return PS_INVALID;rc=fm1_codec_source_encode(fm1_project_source_read,source,source->total,payload+4,FM1_FIXED_COMPRESSED_MAX,&len);if(rc==FM1_CODEC_FULL)return FM1_FIXED_FULL;if(rc!=FM1_CODEC_OK)return PS_IO;put32(payload,(uint32_t)len);memset(payload+4+len,0xff,FM1_FIXED_PAYLOAD-4-len);if(!fm1_fixed_project_valid(payload,FM1_FIXED_PAYLOAD)||preflight(prectx,payload+4,len)!=1||!fm1_fixed_project_valid(payload,FM1_FIXED_PAYLOAD))return PS_INVALID;if(initialize)return pops_initialize(s,slot,name,payload,verify,0,cert,ctx);rc=pops_load(s,slot,verify,0,cert,ctx);if(rc==PS_EMPTY)return PS_INVALID;if(rc!=PS_OK)return rc;return pops_save(s,slot,name,payload,verify,0,cert,ctx);}
int fm1_fixed_project_save(const ps_store *s,uint32_t slot,const char *name,fm1_project_source *source,uint8_t *payload,uint8_t *verify,fm1_fixed_preflight_fn preflight,void *prectx,pops_certify_fn cert,void *ctx){return save(s,slot,name,source,payload,verify,preflight,prectx,cert,ctx,0);}
int fm1_fixed_project_initialize(const ps_store *s,uint32_t slot,const char *name,fm1_project_source *source,uint8_t *payload,uint8_t *verify,fm1_fixed_preflight_fn preflight,void *prectx,pops_certify_fn cert,void *ctx){return save(s,slot,name,source,payload,verify,preflight,prectx,cert,ctx,1);}
static int load(const ps_store *s,uint32_t slot,uint8_t *payload,pops_certify_fn cert,void *ctx,fm1_project_session_valid valid,void *vctx,fm1_project_work *work,uint8_t *session,br_pattern_bank *bank,uint8_t *arena,size_t capacity,br_pattern_snapshot *live,fm1_pattern_song *song,ps_info *info){int rc;uint32_t len;ps_info staged;if(!configured(s)||!payload||!work||overlap(payload,FM1_FIXED_PAYLOAD,work,sizeof *work)||overlap(payload,FM1_FIXED_PAYLOAD,work->pattern,work->pattern?sizeof *work->pattern:0)||overlap(payload,FM1_FIXED_PAYLOAD,work->session,work->session?FM1_PROJECT_SESSION:0)||overlap(payload,FM1_FIXED_PAYLOAD,work->arena,work->arena_capacity)||overlap(payload,FM1_FIXED_PAYLOAD,work->compressed,work->compressed_capacity)||overlap(payload,FM1_FIXED_PAYLOAD,session,FM1_PROJECT_SESSION)||overlap(payload,FM1_FIXED_PAYLOAD,bank,sizeof *bank)||overlap(payload,FM1_FIXED_PAYLOAD,arena,capacity)||overlap(payload,FM1_FIXED_PAYLOAD,live,sizeof *live)||overlap(payload,FM1_FIXED_PAYLOAD,song,sizeof *song))return PS_INVALID;if(info&&(overlap(info,sizeof *info,s,sizeof *s)||overlap(info,sizeof *info,payload,FM1_FIXED_PAYLOAD)||overlap(info,sizeof *info,work,sizeof *work)||overlap(info,sizeof *info,work->pattern,work->pattern?sizeof *work->pattern:0)||overlap(info,sizeof *info,work->session,work->session?FM1_PROJECT_SESSION:0)||overlap(info,sizeof *info,work->arena,work->arena_capacity)||overlap(info,sizeof *info,work->compressed,work->compressed_capacity)||overlap(info,sizeof *info,session,FM1_PROJECT_SESSION)||overlap(info,sizeof *info,bank,sizeof *bank)||overlap(info,sizeof *info,arena,capacity)||overlap(info,sizeof *info,live,sizeof *live)||overlap(info,sizeof *info,song,sizeof *song)))return PS_INVALID;rc=pops_load(s,slot,payload,&staged,cert,ctx);if(rc!=PS_OK)return rc;len=get32(payload);rc=fm1_compressed_project_decode(payload+4,len,valid,vctx,work,session,bank,arena,capacity,live,song);if(rc!=FM1_PROJECT_OK)return PS_INVALID;if(info)*info=staged;return PS_OK;}
int fm1_fixed_project_load(const ps_store *s,uint32_t slot,uint8_t *payload,pops_certify_fn cert,void *ctx,fm1_project_session_valid valid,void *vctx,fm1_project_work *work,uint8_t *session,br_pattern_bank *bank,uint8_t *arena,size_t capacity,br_pattern_snapshot *live,fm1_pattern_song *song){return load(s,slot,payload,cert,ctx,valid,vctx,work,session,bank,arena,capacity,live,song,0);}
int fm1_fixed_project_load_info(const ps_store *s,uint32_t slot,uint8_t *payload,pops_certify_fn cert,void *ctx,fm1_project_session_valid valid,void *vctx,fm1_project_work *work,uint8_t *session,br_pattern_bank *bank,uint8_t *arena,size_t capacity,br_pattern_snapshot *live,fm1_pattern_song *song,ps_info *info){if(!info)return PS_INVALID;return load(s,slot,payload,cert,ctx,valid,vctx,work,session,bank,arena,capacity,live,song,info);}
